 257.14}, {"nome": "PLATAFORMA PROFT 31/11 ZENITH", "valor": 99.0}], "dizimo": 2476.12}]$json$::jsonb;
  v_depara jsonb := $dp${
  "Acocimentos": "Açocimentos",
  "Assoline": "Assoline",
  "Belem": "Belém",
  "Cejatel": "Cematel",
  "Engecal": "Engecal",
  "Frete": "Freteiro (Roberto)",
  "Iran": "Cermati (Iran)",
  "Iran/ CERMATI": "Cermati (Iran)",
  "Isotec": "Isotec",
  "Lucas": "Lucas",
  "Madeira": "Madeira",
  "Pedra": "Pedra / Duralfoil",
  "Pedra / Duralfoil": "Pedra / Duralfoil",
  "Programas e mentorias": "Programas e Mentorias",
  "Zingoti": "Zingoti"
}$dp$::jsonb;
  v_criar text[] := array['Madeira', 'Pedra / Duralfoil'];
  v_lar uuid;
  v_conta uuid;
  m jsonb; x jsonb;
  v_mes date; v_data date;
  v_cli uuid; v_cat uuid; v_desp uuid; v_diz uuid;
  v_nome text;
begin
  select ml.lar_id into v_lar from public.membros ml join auth.users u on u.id = ml.user_id
  where u.email = 'jhonythiago@gmail.com' and ml.papel = 'dono' limit 1;
  if v_lar is null then raise exception 'Lar do jhonythiago@gmail.com não encontrado.'; end if;

  if exists (select 1 from public.entradas where lar_id = v_lar and competencia between '2025-01-01' and '2025-12-01') then
    raise exception 'A importação de 2025 já foi feita antes. Nada foi gravado.';
  end if;

  select id into v_conta from public.contas where lar_id = v_lar and nome = 'Histórico da planilha';
  if v_conta is null then
    insert into public.contas (lar_id, nome, natureza, tipo, saldo_inicial, data_saldo_inicial, ativa, ordem)
    values (v_lar, 'Histórico da planilha', 'PF', 'dinheiro', 0, '2026-09-30', false, 999)
    returning id into v_conta;
  end if;

  -- Confere os clientes antes de gravar qualquer coisa.
  for x in select to_jsonb(t) from jsonb_each_text(v_depara) t loop
    if not exists (select 1 from public.clientes where lar_id = v_lar and lower(trim(nome)) = lower(trim(x->>'value')))
       and not (x->>'value' = any(v_criar)) then
      raise exception 'Cliente "%" não encontrado no seu cadastro. Nada foi gravado.', x->>'value';
    end if;
  end loop;

  delete from public.meses_fechados where lar_id = v_lar and competencia between '2025-01-01' and '2025-12-01';

  for m in select * from jsonb_array_elements(v_dados) loop
    v_mes := make_date(2025, (m->>'mes')::int, 1);
    v_data := make_date(2025, (m->>'mes')::int, (m->>'ultimo')::int);

    -- Renda da empresa (por cliente)
    select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'entrada' and lower(trim(nome)) = 'renda da empresa' limit 1;
    if v_cat is null then select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'renda_empresa' order by ordem limit 1; end if;
    for x in select * from jsonb_array_elements(m->'clientes') loop
      v_nome := coalesce(v_depara->>(x->>'nome'), x->>'nome');
      select id into v_cli from public.clientes where lar_id = v_lar and lower(trim(nome)) = lower(trim(v_nome)) order by criado_em limit 1;
      if v_cli is null then
        insert into public.clientes (lar_id, nome) values (v_lar, v_nome) returning id into v_cli;
      end if;
      insert into public.entradas (lar_id, data, competencia, valor, descricao, categoria_id, cliente_id, conta_id)
      values (v_lar, v_data, v_mes, (x->>'valor')::numeric, 'Importado da planilha', v_cat, v_cli, v_conta);
    end loop;

    -- Restituição de imposto (grupo Renda Empresa: entra no dízimo)
    for x in select * from jsonb_array_elements(m->'restituicao') loop
      select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'entrada' and lower(trim(nome)) = 'restituição de imposto' limit 1;
      if v_cat is null then
        insert into public.categorias (lar_id, nome, tipo, grupo, ordem)
        values (v_lar, 'Restituição de imposto', 'entrada', 'renda_empresa', 15)
        returning id into v_cat;
      end if;
      insert into public.entradas (lar_id, data, competencia, valor, descricao, categoria_id, conta_id)
      values (v_lar, v_data, v_mes, (x->>'valor')::numeric, x->>'nome', v_cat, v_conta);
    end loop;

    -- Outras rendas (fora do dízimo)
    for x in select * from jsonb_array_elements(m->'outras') loop
      select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'entrada'
        and lower(trim(nome)) = case when lower(x->>'nome') like 'aluguel%' then 'aluguel recebido' else 'outras rendas' end limit 1;
      if v_cat is null then select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'outras_rendas' order by ordem limit 1; end if;
      insert into public.entradas (lar_id, data, competencia, valor, descricao, categoria_id, conta_id)
      values (v_lar, v_data, v_mes, (x->>'valor')::numeric, x->>'nome', v_cat, v_conta);
    end loop;

    -- Contas do mês (pagas)
    for x in select * from jsonb_array_elements(m->'saidas') loop
      select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'saida' and lower(trim(nome)) = lower(trim(x->>'cat')) limit 1;
      if v_cat is null then select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'saida' and lower(trim(nome)) = 'outras despesas' limit 1; end if;
      if v_cat is null then select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'despesa_casa' order by ordem limit 1; end if;
      insert into public.despesas (lar_id, descricao, categoria_id, competencia, vencimento, valor, origem)
      values (v_lar, x->>'nome', v_cat, v_mes, make_date(2025, (m->>'mes')::int, (x->>'dia')::int), (x->>'valor')::numeric, 'conta')
      returning id into v_desp;
      insert into public.pagamentos (lar_id, despesa_id, data, valor, conta_id)
      values (v_lar, v_desp, make_date(2025, (m->>'mes')::int, (x->>'dia')::int), (x->>'valor')::numeric, v_conta);
    end loop;

    -- Pix e dinheiro do dia a dia
    select id into v_cat from public.categorias where lar_id = v_lar and tipo = 'saida' and lower(trim(nome)) = 'pix e dinheiro do dia a dia' limit 1;
    if v_cat is null then select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'despesa_casa' order by ordem limit 1; end if;
    for x in select * from jsonb_array_elements(m->'pix') loop
      insert into public.despesas (lar_id, descricao, categoria_id, competencia, vencimento, valor, origem)
      values (v_lar, x->>'nome', v_cat, v_mes, v_data, (x->>'valor')::numeric, 'avulsa')
      returning id into v_desp;
      insert into public.pagamentos (lar_id, despesa_id, data, valor, conta_id)
      values (v_lar, v_desp, v_data, (x->>'valor')::numeric, v_conta);
    end loop;

    -- Dízimo: fica igual ao valor pago na planilha.
    perform public._sync_dizimo(v_lar, v_mes);
    if (m->>'dizimo')::numeric > 0 then
      select id into v_diz from public.despesas where lar_id = v_lar and origem = 'dizimo' and competencia = v_mes limit 1;
      if v_diz is null then
        select id into v_cat from public.categorias where lar_id = v_lar and grupo = 'dizimo' order by (lower(nome) like 'd%zimo%') desc, ordem limit 1;
        insert into public.despesas (lar_id, descricao, categoria_id, competencia, vencimento, valor, origem)
        values (v_lar, 'Dízimo (pago conforme planilha)', v_cat, v_mes, v_data, (m->>'dizimo')::numeric, 'dizimo')
        returning id into v_diz;
      end if;
      insert into public.pagamentos (lar_id, despesa_id, data, valor, conta_id)
      values (v_lar, v_diz, v_data, (m->>'dizimo')::numeric, v_conta);
      update public.despesas set valor = (m->>'dizimo')::numeric, descricao = 'Dízimo (pago conforme planilha)' where id = v_diz;
    end if;

    insert into public.meses_fechados (lar_id, competencia) values (v_lar, v_mes) on conflict do nothing;
  end loop;

  raise notice 'Importação de 2025 concluída.';
end
$imp$;
